   "content": "from __future__ import annotations
from typing import List
from textkit.normalize_whitespace import normalize_whitespace

def _wrap(text: str, width: int) -> List[str]:
    words = normalize_whitespace(text).split()
    lines, cur, length = [], [], 0
    for w in words:
        s = 1 if cur else 0
        if length + s + len(w) <= width:
            cur.append(w)
            length += s + len(w)
        else:
            lines.append(" ".join(cur))
            cur, length = [w], len(w)
    if cur: lines.append(" ".join(cur))
    return lines

def justify_text(text: str, width: int) -> List[str]:
    if width < 1: raise ValueError("width < 1")
    lines = _wrap(text, width)
    res = []
    for i, line in enumerate(lines):
        words = line.split()
        if i == len(lines) - 1 or len(words) <= 1 or len(line) >= width:
            res.append(line)
            continue
        total_sp = width - sum(len(w) for w in words)
        gaps = len(words) - 1
        base, extra = divmod(total_sp, gaps)
        l = []
        for j in range(gaps):
            l.append(words[j])
            l.append(" " * (base + (1 if j < extra else 0)))
        l.append(words[-1])
        res.append("".join(l))
    return res"
  }
 },
