{"thought": "I will attempt to write the file one more time, ensuring the JSON is valid and the content is correctly escaped. I will use a slightly more compact version of the code to minimize the risk of escaping errors.", "action": {"tool": "write_file", "args": {"path": "src/textkit/split_sentences.py", "content": "from __future__ import annotations
from typing import List
from textkit.normalize_whitespace import normalize_whitespace

def split_sentences(text: str) -> List[str]:
    if not text.strip():
        return []
    words = normalize_whitespace(text).split()
    if not words:
        return []
    abbr = {"Mr.", "Mrs.", "Ms.", "Dr.", "Prof.", "St.", "vs.", "e.g.", "i.e."}
    terms = (".", "!", "?")
    clos = ("'", ")", "]", "}")
    open_c = ("'", "(", "[", "{")
    sentences, current = [], []
    for i, word in enumerate(words):
        current.append(word)
        is_b = False
        is_a = word in abbr or (len(word) == 2 and word[0].isalpha() and word[1] == '.')
        if not is_a:
            idx = len(word) - 1
            while idx >= 0 and word[idx] in clos:
                idx -= 1
            if idx >= 0 and word[idx] in terms:
                if i + 1 < len(words):
                    nxt = words[i + 1]
                    if nxt[0].isupper() or nxt[0].isdigit() or nxt[0] in open_c:
                        is_b = True
                else:
                    is_b = True
        if is_b:
            sentences.append(" ".join(current))
            current = []
    if current:
        sentences.append(" ".join(current))
    return sentences
"}}, "messages": []}

